            buscarComoOrigen(userId, cb);
        });
    }
    function buscarComoDestino(userId, cb) {
        const url = '/api/relations?toId=' + userId + '&toType=USER&relationTypeGroup=COMMON';
        $ctx.http.get(url).subscribe(function(rels) {
            const candidatos = (rels || []).filter(r =>
