                (!REL_GUARD_TO_USER || r.type === REL_GUARD_TO_USER)
            );
            if (candidatos.length === 0) { cb(null); return; }
            const assetId = candidatos[0].from.id;
            $ctx.http.get('/api/asset/' + assetId).subscribe(function(asset) { cb(asset); }, function() { cb(null); });
        }, function() { cb(null); });
    }
    function buscarComoOrigen(userId, cb) {
        const url = '/api/relations?fromId=' + userId + '&fromType=USER&relationTypeGroup=COMMON';
        $ctx.http.get(url).subscribe(function(rels) {
            const candidatos = (rels || []).filter(r =>
                r.to && r.to.entityType === 'ASSET' &&
                (!REL_GUARD_TO_USER || r.type === REL_GUARD_TO_USER)
            );
            if (candidatos.length === 0) { cb(null); return; }
            const assetId = candidatos[0].to.id;
            $ctx.http.get('/api/asset/' + assetId).subscribe(function(asset) { cb(asset); }, function() { cb(null); });
        }, function() { cb(null); });
    }
    function obtenerModoEntrada(guardId, cb) {
        $ctx.http.get('/api/plugins/telemetry/ASSET/' + guardId + '/values/attributes').subscribe(function(attrs) {
            const found = (attrs || []).find(a => (a.key || '').toLowerCase() === MODE_ATTRIBUTE.toLowerCase());
