        }, function() { cb('numero'); });
    }
    // Relación real en producción: Grupo_Riego (ASSET, origen) --Maneja--> Guarda (destino).
    function obtenerGruposDeGuarda(guardId, cb) {
        const url = '/api/relations?toId=' + guardId + '&toType=ASSET&relationTypeGroup=COMMON';
        $ctx.http.get(url).subscribe(function(rels) {
            const targetIds = (rels || [])
                .filter(r => r.from && r.from.entityType === 'ASSET' && (!REL_GUARD_TO_GROUP || r.type === REL_GUARD_TO_GROUP))
                .map(r => r.from.id);
            if (targetIds.length === 0) { cb([]); return; }
            cargarAssetsPorId(targetIds, cb);
        }, function() { cb([]); });
    }
    function cargarAssetsPorId(ids, cb) {
        const url = '/api/assets?assetIds=' + ids.join(',');
        $ctx.http.get(url).subscribe(function(assets) { cb(assets || []); }, function() { cb([]); });
    }
    // ============================================================
    // TABLA: columnas de AYER y HOY
    // ============================================================
    function renderTabla() {
        if (!guardAsset) return;
        $container.find('#days-header-row').empty();
        $container.find('#assets-body').empty();
        if (groupAssets.length === 0) {
            mostrarError('No tienes ningún grupo de riego asignado todavía. Contacta con el administrador.');
            return;
        }
        cargarAtributosGrupos(groupAssets, function(assetsConAtributos) {
            assetsConAtributos.sort((a, b) => {
                const ia = ORDEN_GRUPOS_EXCEL.indexOf(a.name);
                const ib = ORDEN_GRUPOS_EXCEL.indexOf(b.name);
                const posA = ia === -1 ? Number.MAX_SAFE_INTEGER : ia;
                const posB = ib === -1 ? Number.MAX_SAFE_INTEGER : ib;
                if (posA !== posB) return posA - posB;
                return a.name.localeCompare(b.name, 'es');
            });
            buildTable(assetsConAtributos);
            cargarValoresDias(assetsConAtributos);
        });
    }
    function cargarAtributosGrupos(assets, callback) {
        assets.forEach(a => { a.sector = 999999; });
        let idx = 0;
        const BATCH_SIZE = 5;
        function next() {
            if (idx >= assets.length) { callback(assets); return; }
            const batch = assets.slice(idx, idx + BATCH_SIZE);
            idx += BATCH_SIZE;
            let completed = 0;
            batch.forEach(asset => {
                $ctx.http.get('/api/plugins/telemetry/ASSET/' + asset.id.id + '/values/attributes').subscribe(function(data) {
                    (data || []).forEach(attr => {
                        if ((attr.key || '').toLowerCase() === 'sector') asset.sector = parseFloat(attr.value) || attr.value;
                    });
                    if (++completed === batch.length) next();
                }, function() { if (++completed === batch.length) next(); });
            });
        }
        next();
    }
    // Devuelve, para un valor "asset.sector" tal cual viene del atributo, el texto que se
    // muestra/usa en filtros: "-" si el grupo no tiene sector asignado (999999), o el propio
    // valor convertido a texto en caso contrario.
    function sectorDisplay(sector) {
        return sector === 999999 || sector === undefined ? '-' : String(sector);
    }
    function buildTable(assets) {
        const $headerRow = $container.find('#days-header-row').empty();
        const $body = $container.find('#assets-body').empty();

        // Desplegable de SECTOR: solo con los sectores que de verdad tienen algún grupo
        // asignado a ESTE guarda (no la lista completa de sectores del sistema). Si el
        // guarda no tiene ningún grupo de un sector, ese sector ni aparece en la lista.
        const uniqueSectors = [...new Set(assets.map(a => sectorDisplay(a.sector)))]
            .sort((a, b) => a.localeCompare(b, 'es', { numeric: true }));
        let sectorOptionsHtml = '<option value="">Todos</option>';
        uniqueSectors.forEach(function(s) {
            sectorOptionsHtml += '<option value="' + s + '">' + s + '</option>';
        });

        $headerRow.append(
            '<th class="col-fixed-1">SECTOR<br>' +
            '<select id="filtro-sector" class="filter-select">' + sectorOptionsHtml + '</select>' +
            '</th>'
        );
        $headerRow.append('<th class="col-fixed-2">GRUPO<br><input type="text" id="filtro-grupo" class="filter-input" placeholder="Filtrar..."></th>');
        $headerRow.append('<th class="col-ayer">AYER<span class="col-date">' + formatCorta(ayer) + '</span></th>');
        $headerRow.append('<th class="col-hoy">HOY<span class="col-date">' + formatCorta(hoy) + '</span></th>');

        // Filtro combinado: sector seleccionado (si hay) Y texto de grupo (si hay).
        function aplicarFiltros() {
            const sectorSel = $container.find('#filtro-sector').val() || '';
            const q = ($container.find('#filtro-grupo').val() || '').toLowerCase().trim();
            $body.find('tr').each(function() {
                const $tr = $(this);
                const sectorFila = $tr.attr('data-sector') || '';
                const nombreFila = $tr.find('td.col-fixed-2').text().toLowerCase();
                const sectorMatch = (sectorSel === '') || (sectorFila === sectorSel);
                const nombreMatch = nombreFila.includes(q);
                $tr.toggle(sectorMatch && nombreMatch);
            });
        }
        $container.find('#filtro-grupo').off('input').on('input', aplicarFiltros);
        $container.find('#filtro-sector').off('change').on('change', aplicarFiltros);

        assets.forEach(asset => {
            const secDisplay = sectorDisplay(asset.sector);
            const inputModeAttr = modoEntrada === 'numero' ? 'inputmode="numeric"' : '';
            const inputClass = modoEntrada === 'texto' ? 'day-input-texto' : 'day-input-numero';
            const rowHtml = '<tr id="row-' + asset.id.id + '" data-sector="' + secDisplay + '">' +
                '<td class="col-fixed-1">' + secDisplay + '</td>' +
                '<td class="col-fixed-2">' + nombreConRemota(asset.name) + '</td>' +
                '<td class="day-cell day-cell-ayer">' +
                    '<input type="text" ' + inputModeAttr + ' class="day-input ' + inputClass + '" ' +
                    'id="input-ayer-' + asset.id.id + '" data-asset-id="' + asset.id.id + '" data-day="ayer">' +
                '</td>' +
                '<td class="day-cell day-cell-hoy">' +
                    '<input type="text" ' + inputModeAttr + ' class="day-input ' + inputClass + '" ' +
                    'id="input-hoy-' + asset.id.id + '" data-asset-id="' + asset.id.id + '" data-day="hoy">' +
                '</td>' +
                '</tr>';
            $body.append($(rowHtml));
        });
        attachInputHandlers();
    }
    function attachInputHandlers() {
        $container.find('.day-input').off('blur').on('blur', function() {
            guardarCelda($(this));
        });
        $container.find('.day-input').off('keydown').on('keydown', function(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                $(this).blur();
            }
        });
        if (modoEntrada === 'numero') {
            $container.find('.day-input').off('input').on('input', function() {
                const v = $(this).val();
                const cleaned = v.replace(/[^0-9]/g, '');
                if (cleaned !== v) $(this).val(cleaned);
            });
        }
    }
    // ============================================================
    // GUARDADO (hoy y ayer)
    // ============================================================
    // Misma lógica de zona horaria que el widget de "Caudal manual" (Madrid,
    // con cambio de hora de verano/invierno el último domingo de marzo/octubre).
    function madridOffsetMs(t) {
        function lastSundayUtc1(y, m) {
            const last = new Date(Date.UTC(y, m + 1, 0));
            return Date.UTC(y, m, last.getUTCDate() - last.getUTCDay(), 1, 0, 0);
        }
        const y = new Date(t).getUTCFullYear();
        return (t >= lastSundayUtc1(y, 2) && t < lastSundayUtc1(y, 9)) ? 7200000 : 3600000;
    }
    // Devuelve el ts de las 00:00:00 y el de las 23:59:59 del día indicado
    // (objeto Date), en hora de Madrid. Con esto, caudal_guarda queda como
    // un escalón plano en las gráficas, igual que hace el widget de Caudal
    // manual. Se usa tanto para "hoy" como para "ayer".
    function limitesDelDia(fecha) {
        const ahora = fecha.getTime();
        const off = madridOffsetMs(ahora);
        const dLoc = new Date(ahora + off);
        dLoc.setUTCHours(0, 0, 0, 0);
        const inicioDiaTs = dLoc.getTime() - off;
        const finDiaTs = inicioDiaTs + 86400000 - 1000; // 23:59:59 del día
        return { inicio: inicioDiaTs, fin: finDiaTs };
    }
    function tsMediodia(fecha) {
        return new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), 12, 0, 0).getTime();
    }
    function guardarCelda($input) {
        const assetId = $input.data('asset-id');
        const day = $input.data('day') === 'ayer' ? 'ayer' : 'hoy';
        const fecha = day === 'ayer' ? ayer : hoy;
        const valorNuevo = ($input.val() || '').trim();
        const valorAnterior = $input.data('valor-anterior') || '';
        if (valorNuevo === valorAnterior) return;
        const key = modoEntrada === 'texto' ? KEY_TEXT : KEY_NUMERIC;
        if (valorNuevo === '') {
            borrarValorDia($input, assetId, key, valorAnterior, fecha);
            return;
        }
        if (modoEntrada === 'numero' && isNaN(valorNuevo)) {
            alert('Este grupo solo admite valores numéricos (caudal en L/s).');
            $input.val(valorAnterior);
            return;
        }
        const valorAGuardar = modoEntrada === 'numero' ? Number(valorNuevo) : valorNuevo;
        $input.css('background-color', '#fff9c4');
        if (modoEntrada === 'numero') {
            guardarDosPuntosDelDia($input, assetId, key, valorAGuardar, valorNuevo, valorAnterior, fecha);
        } else {
            guardarPuntoUnico($input, assetId, key, valorAGuardar, valorNuevo, valorAnterior, fecha);
        }
    }
    // Modo texto (Fran): un único punto a mediodía del día correspondiente,
    // para apuntar la nota. No se va a graficar, así que no necesita dos puntos.
    function guardarPuntoUnico($input, assetId, key, valorAGuardar, valorNuevo, valorAnterior, fecha) {
        const payload = { ts: tsMediodia(fecha), values: {} };
        payload.values[key] = valorAGuardar;
        $ctx.http.post('/api/plugins/telemetry/ASSET/' + assetId + '/timeseries/ANY', payload).subscribe(function() {
            $input.data('valor-anterior', valorNuevo);
            flashInput($input, '#c8e6c9');
        }, function() {
            alert('Error al guardar el dato. Se restaura el valor anterior.');
            $input.val(valorAnterior);
            flashInput($input, '#ffcdd2');
        });
    }
    // Modo numérico: igual que hace el widget de "Caudal manual" — un punto
    // a las 00:00 y otro a las 23:59:59 del día correspondiente (hoy o ayer),
    // mismo valor en los dos, para que en las gráficas se vea como un
    // escalón plano durante todo ese día.
    function guardarDosPuntosDelDia($input, assetId, key, valorAGuardar, valorNuevo, valorAnterior, fecha) {
        const limites = limitesDelDia(fecha);
        const payloadInicio = { ts: limites.inicio, values: {} };
        payloadInicio.values[key] = valorAGuardar;
        const payloadFin = { ts: limites.fin, values: {} };
        payloadFin.values[key] = valorAGuardar;
        let pendientes = 2;
        let huboError = false;
        [payloadInicio, payloadFin].forEach(function(payload) {
            $ctx.http.post('/api/plugins/telemetry/ASSET/' + assetId + '/timeseries/ANY', payload).subscribe(function() {
                pendientes--;
                if (pendientes === 0) {
                    $input.data('valor-anterior', valorNuevo);
                    flashInput($input, huboError ? '#ffe0b2' : '#c8e6c9');
                }
            }, function() {
                huboError = true;
                pendientes--;
                if (pendientes === 0) {
                    alert('Error al guardar el dato. Se restaura el valor anterior.');
                    $input.val(valorAnterior);
                    flashInput($input, '#ffcdd2');
                }
            });
        });
    }
    function borrarValorDia($input, assetId, key, valorAnterior, fecha) {
        let startTs, endTs;
        if (modoEntrada === 'numero') {
            const limites = limitesDelDia(fecha);
            startTs = limites.inicio - 1000;
            endTs = limites.fin + 1000;
        } else {
            const ts = tsMediodia(fecha);
            startTs = ts - 1000;
            endTs = ts + 1000;
        }
        const urlDelete = '/api/plugins/telemetry/ASSET/' + assetId + '/timeseries/delete?keys=' + key + '&startTs=' + startTs + '&endTs=' + endTs;
        $ctx.http.delete(urlDelete).subscribe(function() {
            $input.data('valor-anterior', '');
            flashInput($input, '#eceff1');
        }, function() {
            alert('No se pudo borrar el valor.');
            $input.val(valorAnterior);
        });
    }
    function flashInput($input, color) {
        $input.css('background-color', color);
        setTimeout(() => $input.css('background-color', ''), 900);
    }
    // ============================================================
    // CARGA DE LOS VALORES DE HOY Y AYER (si ya se habían guardado antes)
    // ============================================================
    function cargarValoresDias(assets) {
        const key = modoEntrada === 'texto' ? KEY_TEXT : KEY_NUMERIC;
        const limAyer = limitesDelDia(ayer);
        const limHoy = limitesDelDia(hoy);
        const startTs = limAyer.inicio - 1000;
        const endTs = limHoy.fin + 1000;
        let idx = 0;
        const BATCH_SIZE = 5;
        function next() {
            if (idx >= assets.length) return;
            const batch = assets.slice(idx, idx + BATCH_SIZE);
            idx += BATCH_SIZE;
            let completed = 0;
            batch.forEach(asset => {
                const url = '/api/plugins/telemetry/ASSET/' + asset.id.id + '/values/timeseries?keys=' + key + '&startTs=' + startTs + '&endTs=' + endTs + '&limit=10';
                $ctx.http.get(url).subscribe(function(data) {
                    const items = (data && data[key]) ? data[key] : [];
                    const itemHoy = items.find(it => it.ts >= limHoy.inicio && it.ts <= limHoy.fin);
                    const itemAyer = items.find(it => it.ts >= limAyer.inicio && it.ts <= limAyer.fin);
                    if (itemHoy) {
                        const $inputHoy = $container.find('#input-hoy-' + asset.id.id);
                        $inputHoy.val(itemHoy.value);
                        $inputHoy.data('valor-anterior', String(itemHoy.value));
                    }
                    if (itemAyer) {
                        const $inputAyer = $container.find('#input-ayer-' + asset.id.id);
                        $inputAyer.val(itemAyer.value);
                        $inputAyer.data('valor-anterior', String(itemAyer.value));
                    }
                    if (++completed === batch.length) next();
                }, function() { if (++completed === batch.length) next(); });
            });
        }
        next();
    }
    setTimeout(iniciar, 200);
};
